from taf.internal.aliasing import aliasing_scope
from taf.analyzer.iperf_throughput.facade import IperfThroughput


class iperf_throughput(object):
    """
    Example
    https://confluence.ext.net.nokia.com/pages/viewpage.action?pageId=1229135222

    .. code-block:: Robot

        Example of Test cases:
            *** Settings ***

            Library    taf.analyzer.iperf_throughput    WITH NAME    tput



            *** Test Cases ***
            Run Sample
                tput.create_iperf_server_udp_throughput    log=<path of iperf log file from server>    alias=iperf_server
                tput.create_iperf_client_udp_throughput    log=<path of iperf log file from client>    alias=iperf_client

                ${list_of_throughputs}    Create list  iperf_server    iperf_client
                tput.analyze    throughputs=${list_of_throughputs}

                ${server_output}    tput.get_throughput    throughput=iperf_server
                Log    ${server_output}

                ${client_output}    tput.get_throughput    throughput=iperf_client
                Log    ${client_output}
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope(lookup_arg='throughput',
                                           lookup_type=IperfThroughput)

    def create_iperf_client_udp_throughput(self,
                                           log,
                                           column=None,
                                           throughput_records_output=None,
                                           time_range=None,
                                           alias=None):
        """

        Create throughput instance for iperf2 client side udp log.
        This throughput will only calculate the value per connection
        if there are multiple connections, accumulation of multiple connections per second will not be care

        :param log: iperf log file path
        :type log: str
        :param column: (optional) the column for comparison in log, 'bandwidth' by default,
        'transfer' is an option
        :type column: str
        :param throughput_records_output: (optional) throughput records output dict object
        :type throughput_records_output: dict
        :param time_range: a range of times only in which the data will be calculated.
        [20,] - 1st 20 seconds of datatransfer will be out of time_ranged.
        [10, 40] - data from 10.0 to 40.0 will be in time range
        :type time_range: Union[List[int], List[str], tuple[int], tuple[str]
        :param alias: (optional) alias for the new Throughput class instance, default is None
        :type alias: str
        :return: Throughput class instance
        """
        time_range = self._convert_robot_sequence_to_tuple(time_range) if time_range else None
        throughput = IperfThroughput.create_iperf_client_udp_throughput(log,
                                                                        column,
                                                                        throughput_records_output,
                                                                        time_range)
        self.store.add(throughput, alias)
        return throughput

