    def analyze(self, throughputs=None):
        """
        Analyze and calculate throughput.

        :param throughputs: (optional) alias list for the Throughput class instance
        :type cells: list[str]
        :return: None
        """
        if throughputs is None:
            throughputs = [self.store.DEFAULT_ALIAS]
        throughput_instances = [self.store.get(alias) for alias in throughputs]
        IperfThroughput.analyze(throughput_instances)

    @lookup_handler.implicit_lookup
    def get_throughput(self, throughput=None):
        """
        Get the calculated throughput result.

        :param throughput: (optional) alias for the Throughput class instance
        :type throughput: str
        :return: List[dict] for the calculated throughput result, e.g.
        [{'connection':
            {'connection_id': '3', 'server_addr': '10.44.35.224',
            'server_port': '50006', 'client_addr': '10.47.55.164', 'client_port': '40151'},
        'peak': {'value': 5060.0, 'unit': 'Kbits/sec'},
        'average': {'value': 5000.0, 'unit': 'Kbits/sec'},
        'minimum': {'value': 4950.0, 'unit': 'Kbits/sec'},
        'count': 120, 'interval':120.0}]
        """
        return [item.to_dict() for item in IperfThroughput.get_throughput(throughput)]

    def _convert_robot_sequence_to_tuple(self, sequence):
        return tuple([float(value) for value in sequence])
